      "default": false
    },
    "timeoutMs": {
      "type": "number",
      "title": "Latency budget (ms)",
      "description": "How long to wait for a decision before letting the request through unchanged",
      "default": 800
    },
    "logDecisions": {
      "type": "boolean",
      "title": "Log decisions",
